// 格式化文件大小
const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 B'
  const k = 1024
  const sizes = ['B', 'KB', 'MB', 'GB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`
}

// 处理文件选择
const handleFileSelect = (event: Event) => {
  const target = event.target as HTMLInputElement
  const files = target.files
  if (files) {
    handleFiles(Array.from(files))
  }
}

// 处理拖拽放置
const handleDrop = (event: DragEvent) => {
  isDragOver.value = false
  const files = event.dataTransfer?.files
  if (files) {
    handleFiles(Array.from(files))
  }
}

// 处理文件
const handleFiles = async (files: File[]) => {
  error.value = ''

  // 检查文件数量
  if (files.length > props.maxFiles) {
    error.value = `最多只能上传 ${props.maxFiles} 个文件`
    return
  }

  // 验证文件
  const validFiles: File[] = []
  for (const file of files) {
    const validationError = validateFile(file)
    if (validationError) {
      error.value = validationError
      return
    }
    validFiles.push(file)
  }

  if (validFiles.length === 0) return

  try {
    loading.value = true

    // 准备上传选项
    const uploadOptions: any = {
      category: selectedCategory.value,
      tags: tags.value.split(',').map(tag => tag.trim()).filter(Boolean)
    }
    if (description.value) uploadOptions.description = description.value

    // 上传文件
    const results = await uploadImages(validFiles, uploadOptions)

    // 更新结果
    uploadResults.value.push(...results)

    // 发出事件
    emit('upload', results)

    // 清空输入
    if (fileInput.value) {
      fileInput.value.value = ''
    }

  } catch (err) {
    const message = err instanceof Error ? err.message : '上传失败'
    error.value = message
    emit('error', message)
  } finally {
    loading.value = false
  }
}

// 触发文件输入
const triggerFileInput = () => {
  if (loading.value) return
  fileInput.value?.click()
}

// 移除结果
const removeResult = (id: string) => {
  const index = uploadResults.value.findIndex(r => r.id === id)
  if (index !== -1) {
    uploadResults.value.splice(index, 1)
  }
}

// 清除结果
const clearResults = () => {
  uploadResults.value = []
}

// 监听分类变化
watch(selectedCategory, (newValue) => {
  if (newValue !== props.defaultCategory) {
    selectedCategory.value = newValue
  }
})

